const input = $json;
const message = input.message_context ?? {};
const hint = input.acquisition_hint ?? {};
const allowedLanding = new Set(['cabine_fotos','plataforma_360','totem_fotos']);
const allowedService = new Set(['cabine_fotos','plataforma_360','totem_fotos']);
const allowedSource = new Set(['paid_ads','organic','direct','referral','unknown']);

const source = allowedSource.has(hint.source) ? hint.source : 'unknown';
const landing = allowedLanding.has(hint.landing_page_code) ? hint.landing_page_code : null;
const service = allowedService.has(hint.service_interest_code) ? hint.service_interest_code : null;
const strong = Boolean(landing && service);

const acquisitionContext = {
  contract_version:'1.0.0',
  correlation_id: message.correlation_id ?? input.correlation_id ?? null,
  source,
  medium: hint.medium ?? null,
  landing_page_code: landing,
  service_interest_code: service,
  campaign_code: hint.campaign_code ?? null,
  utm_source: hint.utm_source ?? null,
  utm_medium: hint.utm_medium ?? null,
  utm_campaign: hint.utm_campaign ?? null,
  utm_content: hint.utm_content ?? null,
  utm_term: hint.utm_term ?? null,
  tracking_token: hint.tracking_token ?? null,
  raw_prefilled_message: hint.raw_prefilled_message ?? message.text ?? null,
  attribution_confidence: strong ? 1 : (source !== 'unknown' ? 0.6 : 0)
};

return {
  json:{
    acquisition_context: acquisitionContext,
    strong_commercial_signal: strong,
    requested_actions: strong || source !== 'unknown' ? [{action:'RECORD_ACQUISITION_TOUCHPOINT'}] : [],
    blockers: []
  }
};
